# ruff: noqa: E501

from fastapi import APIRouter
from fastapi.responses import HTMLResponse

router = APIRouter(include_in_schema=False)

_PREMIUM_PAGE = r"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RoadTalk | Premium</title><style>:root{color-scheme:dark;--bg:#07141b;--panel:#10232e;--text:#f2f7f9;--muted:#abc0c9;--accent:#f2b84b;--good:#70da96;--bad:#ff7979;--line:rgba(255,255,255,.14)}*{box-sizing:border-box}body{margin:auto;max-width:850px;padding:24px;background:var(--bg);color:var(--text);font-family:system-ui}nav,.row{display:flex;gap:12px;flex-wrap:wrap;align-items:center}a{color:var(--text)}.panel{border:1px solid var(--line);background:var(--panel);border-radius:14px;padding:18px;margin:18px 0}.muted{color:var(--muted)}.good{color:var(--good)}.bad{color:var(--bad)}button{padding:11px 14px;background:#07141b;color:#fff;border:1px solid #78909a;border-radius:8px;cursor:pointer;font:inherit}button:disabled{opacity:.55;cursor:not-allowed}:focus-visible{outline:3px solid var(--accent);outline-offset:3px}dl{display:grid;grid-template-columns:max-content 1fr;gap:6px 16px;margin:0}dt{color:var(--muted)}dd{margin:0}.hidden{display:none}section .row{margin-top:16px}</style></head><body><nav aria-label="RoadTalk"><strong>RoadTalk Premium</strong><a href="/">Home</a><a href="/radio">Radio</a><a href="/map">Map</a><a href="/account">Account</a></nav><main><h1>Premium status</h1><p class="muted">Premium never changes who you can hear or talk to. Radio, channels, convoys, the map, notifications, and every other feature you use today stay available without Premium.</p><p id="status" role="status" aria-live="polite">Checking Premium status…</p><section class="panel" aria-labelledby="entitlement-heading"><h2 id="entitlement-heading">Your entitlement</h2><dl id="details" class="hidden"><dt>Plan</dt><dd id="tier"></dd><dt>Entitlement</dt><dd id="entitlement"></dd><dt>Premium experience</dt><dd id="allowed"></dd><dt>Confirmed by</dt><dd id="provenance"></dd><dt>Valid until</dt><dd id="valid-until"></dd></dl><p id="empty" class="muted">No server-confirmed Premium status is shown.</p><div class="row"><button id="check" type="button">Check Premium status</button></div></section><section class="panel" aria-labelledby="purchase-heading"><h2 id="purchase-heading">Purchasing</h2><p>Premium purchase is not available. RoadTalk does not offer checkout, collect payment details, or connect to an app store or payment provider.</p></section></main><script>
const $=id=>document.getElementById(id);let busy=false,expiryTimer=null;
const access=()=>localStorage.getItem('rt_access'),refreshToken=()=>localStorage.getItem('rt_refresh');
const ENTITLEMENT_TEXT={active:'Active',inactive:'Not active',expired:'Expired',revoked:'Revoked'};
async function refresh(){const t=refreshToken();if(!t)return false;const r=await fetch('/api/v1/auth/refresh',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({refresh_token:t})});if(!r.ok)return false;const b=await r.json();localStorage.setItem('rt_access',b.access_token);localStorage.setItem('rt_refresh',b.refresh_token);return true}
async function readStatus(){if(!access()&&!refreshToken())throw Error('Sign in from Account or Radio first.');const send=()=>fetch('/api/v1/me/premium',{cache:'no-store',headers:{Accept:'application/json',Authorization:`Bearer ${access()}`}});let r=await send();if(r.status===401&&await refresh())r=await send();if(!r.ok)throw Error('Premium status is temporarily unavailable.');return r.json()}
function say(text,tone){$('status').textContent=text;$('status').className=tone||''}
function clearStatus(message,tone){if(expiryTimer){clearTimeout(expiryTimer);expiryTimer=null}$('details').classList.add('hidden');$('empty').classList.remove('hidden');for(const id of ['tier','entitlement','allowed','provenance','valid-until'])$(id).textContent='';if(message)say(message,tone)}
function render(s){if(s.availability==='provider_disabled'){clearStatus('Premium is not available in this RoadTalk environment. Your existing RoadTalk features are unchanged.');return}if(s.availability==='provider_unavailable'){clearStatus('Premium status could not be confirmed right now. Nothing has changed; try again later.','bad');return}const validUntil=new Date(s.valid_until),remaining=validUntil.getTime()-Date.now();if(!(remaining>0)){clearStatus('That Premium status is already out of date. Check again.','bad');return}$('tier').textContent=s.tier==='premium'?'Premium':'Free';$('entitlement').textContent=ENTITLEMENT_TEXT[s.entitlement_state]||'None';$('allowed').textContent=s.premium_experience_allowed?'Available':'Not available';$('provenance').textContent='RoadTalk server at '+new Date(s.observed_at).toLocaleTimeString()+(s.provider_mode==='test'?' (deterministic test provider, no billing)':'');$('valid-until').textContent=validUntil.toLocaleTimeString();$('empty').classList.add('hidden');$('details').classList.remove('hidden');say(s.premium_experience_allowed?'Premium is active for this account.':'This account does not have active Premium.',s.premium_experience_allowed?'good':'');if(expiryTimer)clearTimeout(expiryTimer);expiryTimer=setTimeout(()=>clearStatus('Premium status expired and was cleared. Check again to confirm it.'),remaining)}
async function check(){if(busy)return;if(!navigator.onLine){clearStatus('You are offline. Premium status was cleared; check again when you reconnect.','bad');return}busy=true;$('check').disabled=true;say('Checking Premium status…');try{render(await readStatus())}catch(e){clearStatus(e.message,'bad')}finally{busy=false;$('check').disabled=false}}
$('check').addEventListener('click',check);
window.addEventListener('offline',()=>clearStatus('You are offline. Premium status was cleared; check again when you reconnect.','bad'));
void check();
</script></body></html>"""


@router.get("/premium", response_class=HTMLResponse)
async def premium_page() -> HTMLResponse:
    return HTMLResponse(_PREMIUM_PAGE, headers={"Cache-Control": "no-store"})
